export const pdfMessages = Object.fromEntries(Object.entries(rows).map(([language,row])=>[language,Object.fromEntries(keys.map((key,i)=>[key,row[i]]))]));
export const getPdfLocale = (language='de') => ({de:'de-DE',en:'en-GB',fr:'fr-FR',es:'es-ES',it:'it-IT',cs:'cs-CZ',zh:'zh-CN',ja:'ja-JP',ko:'ko-KR',pirate:'en-GB'}[language]||'de-DE');
export const getLocale = getPdfLocale;
export function pdfText(key,values={},language='de') {
  const message=pdfMessages[language]?.[key] ?? pdfMessages.de[key] ?? key;
  return message.replace(/\{(\w+)\}/g,(token,name)=>values[name]===undefined?token:String(values[name]));
}
